using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "EndTurnConditionMatchNoDiceBoostOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/EndTurnConditionMatchNoDiceBoostOmenData")]
public class EndTurnConditionMatchNoDiceBoostOmenData : EndTurnConditionSpecificDiceTierOmenData
{
	public override void ActivateOmen(GameObject target = null)
	{
		counter++;
		if (counter == TriggerAmount)
		{
			base.ActivateOmen(target);
		}
		else
		{
			omenInstance.UpdateOmenCounter();
		}
	}

	public override string OmenConvertedDescription()
	{
		return endOfTurnForEndTurnConditionOmenData.GetEndOfPlayerTurnLocalizedDescription() + base.localizationManager.GetLocalizedSpace() + Smart.Format(GetOmenRawLocalizedDescription(), TriggerAmount - 1, GetOmenConvertedDescriptionBattleAction().LowercaseFirst());
	}
}
